import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 집계 기준은 조회 월에 시작일이 속한 본인 근태 건이다.
// 가정: 마감·승인 상태의 건은 동의를 거절한다.
const LOCKED_STATUSES = ['마감', '승인'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr03204Controller {
  @Post('/attendance-requests/:attendanceRequestId/consent')
  @HttpCode(200)
  async consentAttendanceRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const idText = req.params['attendanceRequestId'];
    if (!/^[0-9]{1,18}$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM attendance_request WHERE attendance_request_id = CAST(:id AS bigint) AND employee_id = CAST(:userId AS bigint)',
        { id: idText, userId: user.id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_REQUEST_NOT_FOUND', '대상 근태 데이터를 찾을 수 없습니다.');
      }
      if (LOCKED_STATUSES.includes(found[0].approvalStatus)) {
        throw new ApiError(409, 'ATTENDANCE_PERIOD_CLOSED', '마감된 기간이거나 승인된 건은 변경할 수 없습니다. 마감 취소 후 다시 시도해 주세요.');
      }
      // 동의 일시를 저장할 컬럼이 schema.sql에 없어 수정 일시만 갱신한다.
      const rows = await db.query(
        'UPDATE attendance_request SET updated_at = now() WHERE attendance_request_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus", now() AS "consentedAt"',
        { id: idText },
      );
      return { consentedAt: rows[0].consentedAt, approvalStatus: rows[0].approvalStatus };
    });
  }

  @Get('/attendance-summaries')
  async listAttendanceSummaries(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const month = typeof q['month'] === 'string' ? (q['month'] as string) : '';
    if (!/^[0-9]{4}-(0[1-9]|1[0-2])$/.test(month)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간은 YYYY-MM 형식으로 입력해 주세요.');
    }
    const pageRaw = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    const page = pageRaw;
    const fromDate = month + '-01';
    return transaction(async (db) => {
      const where =
        'FROM attendance_request WHERE employee_id = CAST(:userId AS bigint) AND start_date >= CAST(:fromDate AS date) AND start_date < (CAST(:fromDate AS date) + interval \'1 month\') GROUP BY attendance_type, approval_status';
      const totalRows = await db.query(
        'SELECT COUNT(*) AS total FROM (SELECT 1 ' + where + ') t',
        { userId: user.id, fromDate },
      );
      // 동의 일시를 저장한 컬럼이 없어 비워 둔다.
      const items = await db.query(
        'SELECT attendance_type AS "attendanceType", approval_status AS "approvalStatus", COUNT(*) AS "count", CAST(NULL AS timestamptz) AS "consentedAt" ' +
          where +
          ' ORDER BY attendance_type, approval_status LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { userId: user.id, fromDate, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }
}

