import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr03204Page({ role, notify }: PageProps) {
  const [monthInput, setMonthInput] = useState('');
  const [month, setMonth] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [consentOpen, setConsentOpen] = useState(false);
  const [requestId, setRequestId] = useState<number | string>('');

  const { data, error, loading, reload } = useData<Page | undefined>(async () => {
    if (!month) {
      return undefined;
    }
    return call<Page>('GET', '/attendance-summaries', role, undefined, { month, page: pageNo, size: SIZE });
  }, [month, pageNo, role]);

  const search = () => {
    setPageNo(0);
    setMonth(monthInput);
  };

  const reset = () => {
    setMonthInput('');
    setMonth('');
    setPageNo(0);
  };

  const consent = async () => {
    if (requestId === '') {
      throw new Error('동의할 근태 ID를 입력해 주세요.');
    }
    await call('POST', '/attendance-requests/' + requestId + '/consent', role, {});
    notify('근무시간 동의를 처리했습니다.');
    setConsentOpen(false);
    setRequestId('');
    reload();
  };

  const columns = [
    { key: 'attendanceType', label: '근태 유형' },
    { key: 'approvalStatus', label: '승인 처리 상태', render: (r: Row) => <Badge value={r.approvalStatus} /> },
    { key: 'count', label: '건수', render: (r: Row) => <Num value={r.count} /> },
    { key: 'consentedAt', label: '동의 일시', render: (r: Row) => <DateText value={r.consentedAt} time /> },
  ];

  return (
    <div className="doc">
      <section className="box">
        <h2>근태집계 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 기간(월 단위)" required hint="예: 2025-03">
            <TextInput value={monthInput} onChange={setMonthInput} placeholder="YYYY-MM" />
          </Field>
        </Filters>
        <Band total={data ? data.total : undefined}>
          <button onClick={() => setConsentOpen(true)}>근무시간 동의</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        {!month ? (
          <p>조회 기간을 입력하고 조회해 주세요.</p>
        ) : loading ? (
          <p>불러오는 중입니다.</p>
        ) : (
          <>
            <DataTable columns={columns} rows={data ? data.items : []} empty="조회 결과가 없습니다." />
            {data ? <Pager page={data.page} size={data.size} total={data.total} onPage={setPageNo} /> : null}
          </>
        )}
      </section>
      {consentOpen ? (
        <Drawer title="근무시간 동의" onClose={() => setConsentOpen(false)}>
          <Form
            onSubmit={consent}
            submit="동의"
            note="마감된 기간이거나 승인된 건은 동의할 수 없습니다. 마감 취소 후 다시 시도해 주세요."
          >
            <Field label="근태 ID" required wide>
              <NumberInput value={requestId} onChange={setRequestId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
